        turbojet::sbe::put_le(block, 24, self.onbehalf_firm.unwrap_or(0));
        write_data_u8(out, "credentials", self.credentials, 128)?;
        write_data_u8(out, "clientIP", self.client_ip, 30)?;
        write_data_u8(out, "clientAppName", self.client_app_name, 30)?;
        write_data_u8(out, "clientAppVersion", self.client_app_version, 30)?;
