/// `SimpleOpenFramingHeaderMessage` (template 0), read where it lies.
#[derive(Clone, Copy)]
pub struct SimpleOpenFramingHeaderMessageRef<'a> {
    sbe_block: &'a [u8],
    sbe_version: u16,
}

impl<'a> turbojet::sbe::Block<'a> for SimpleOpenFramingHeaderMessageRef<'a> {
    #[allow(clippy::too_many_lines)]
    fn wrap(bytes: &'a [u8], block_length: usize, _version: u16) -> Result<(Self, usize), turbojet::sbe::SbeError> {
        let sbe_block = turbojet::sbe::take(bytes, 0, block_length)?;
        let needed = 4;
        if block_length < needed {
            return Err(turbojet::sbe::SbeError::BlockLength { actual: block_length, needed });
        }
        let at = block_length;
        Ok((Self { sbe_block, sbe_version: _version }, at))
    }
}

// The methods are named after the schema's fields, whatever their names suggest to clippy.
#[allow(clippy::wrong_self_convention, clippy::should_implement_trait)]
impl<'a> SimpleOpenFramingHeaderMessageRef<'a> {
    /// The schema version it was encoded in.
    pub fn sbe_version(&self) -> u16 {
        self.sbe_version
    }

    /// `framingHeader` (0).
    pub fn framing_header(&self) -> FramingHeader {
        FramingHeader::decode(self.sbe_block)
    }
}

impl std::fmt::Debug for SimpleOpenFramingHeaderMessageRef<'_> {
    #[allow(clippy::too_many_lines)]
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("SimpleOpenFramingHeaderMessageRef").field("framing_header", &self.framing_header()).finish()
    }
}

/// `SimpleOpenFramingHeaderMessage` (template 0), to encode.
#[derive(Debug, Clone, PartialEq)]
pub struct SimpleOpenFramingHeaderMessage {
    /// `framingHeader` (0).
    pub framing_header: FramingHeader,
}

impl SimpleOpenFramingHeaderMessage {
    /// The length of its block.
    pub const BLOCK_LENGTH: usize = 4;
    /// Its template ID.
    pub const TEMPLATE_ID: u16 = 0;

    /// Appends it to `out`, after a message header.
    ///
    /// # Errors
    ///
    /// If a group has more entries, or a data field more bytes, than its encoding allows. `out` is then as it was.
    pub fn encode_into(&self, out: &mut Vec<u8>) -> Result<(), turbojet::sbe::SbeError> {
        let start = out.len();
        let header = MessageHeader { block_length: 4, template_id: 0, schema_id: SCHEMA_ID, version: SCHEMA_VERSION };
        header.encode(turbojet::sbe::reserve(out, MessageHeader::SIZE));
        let result = self.encode_body(out);
        if result.is_err() {
            out.truncate(start);
        }
        result
    }

    #[allow(clippy::too_many_lines)]
    fn encode_body(&self, out: &mut Vec<u8>) -> Result<(), turbojet::sbe::SbeError> {
        let block = turbojet::sbe::reserve(out, 4);
        self.framing_header.encode(block);
        Ok(())
    }
}

impl turbojet::sbe::Encode for SimpleOpenFramingHeaderMessage {
    const TEMPLATE_ID: u16 = 0;

    fn encode_into(&self, out: &mut Vec<u8>) -> Result<(), turbojet::sbe::SbeError> {
        SimpleOpenFramingHeaderMessage::encode_into(self, out)
    }
}

