fn read_group_size_encoding<'a, E: turbojet::sbe::Block<'a>>(
    bytes: &'a [u8],
    at: usize,
    version: u16,
) -> Result<(turbojet::sbe::Group<'a, E>, usize), turbojet::sbe::SbeError> {
    let dimension = GroupSizeEncoding::decode(turbojet::sbe::take(bytes, at, GroupSizeEncoding::SIZE)?);
    let at = at + GroupSizeEncoding::SIZE;
    let rest = bytes.get(at..).ok_or(turbojet::sbe::SbeError::Truncated)?;
    let (group, len) = turbojet::sbe::Group::scan(
        rest,
        turbojet::sbe::length(dimension.block_length)?,
        turbojet::sbe::length(dimension.num_in_group)?,
        version,
    )?;
    Ok((group, at + len))
}

fn write_group_size_encoding(
    out: &mut Vec<u8>,
    name: &'static str,
    block_length: usize,
    count: usize,
) -> Result<(), turbojet::sbe::SbeError> {
    let dimension = GroupSizeEncoding {
        block_length: turbojet::sbe::count(name, block_length, u16::MAX)?,
        num_in_group: turbojet::sbe::count(name, count, u8::MAX)?,
    };
    dimension.encode(turbojet::sbe::reserve(out, GroupSizeEncoding::SIZE));
    Ok(())
}

fn read_data_u8(bytes: &[u8], at: usize) -> Result<(&[u8], usize), turbojet::sbe::SbeError> {
    let len = turbojet::sbe::length(turbojet::sbe::get_le::<u8>(turbojet::sbe::take(bytes, at, 1)?, 0))?;
    Ok((turbojet::sbe::take(bytes, at + 1, len)?, at + 1 + len))
}

fn write_data_u8(out: &mut Vec<u8>, name: &'static str, data: &[u8], max: u8) -> Result<(), turbojet::sbe::SbeError> {
    let len = turbojet::sbe::count(name, data.len(), max)?;
    turbojet::sbe::put_le(turbojet::sbe::reserve(out, 1), 0, len);
    out.extend_from_slice(data);
    Ok(())
}
